    'Download SBOM': {de: 'SBOM herunterladen'},
    Privacy: {de: 'Datenschutz'},
    'What the system sends to outside sources': {de: 'Was das System nach außen sendet'},
    // task 236: openccu-lite's own licence (Apache 2.0) and its disclaimer of warranty - in German
    // OpenCCU's wording with openccu-lite in its place (the maintainer), not a translation
