    'Delete {name}': {de: '{name} löschen'},
    'Something in here reports a problem': {de: 'Etwas hier drin meldet ein Problem'},
    // B-46: STICKY_UNREACH alone - the device answers again, the outage is not acknowledged yet
    'was unreachable': {de: 'war nicht erreichbar'},
    // occulited task 19: the Control app's quiet mark while its live stream is not open
