function initial(): Language {
    try {
        const stored = localStorage.getItem('ol.language');
        if (stored === 'de' || stored === 'en') return stored;
    } catch {
        /* storage may be unavailable */
    }
    return navigator.language.toLowerCase().startsWith('de') ? 'de' : 'en';
}

export const i18n = $state({language: initial()});

// 28.5, the Node-RED half: the editor's language is a localStorage key of the origin it is served
// from ("editor-language", read before the editor loads), and an addon behind lighttpd shares the
// shell's origin. The shell keeps it in step so a framed editor speaks the shell's language;
// the values are Node-RED's own codes.
export function syncEditorLanguage(l: Language): void {
    try {
        localStorage.setItem('editor-language', l === 'de' ? 'de' : 'en-US');
    } catch {
        /* ignore */
    }
}
syncEditorLanguage(i18n.language);

export function setLanguage(l: Language): void {
    i18n.language = l;
    try {
        localStorage.setItem('ol.language', l);
    } catch {
        /* ignore */
    }
    syncEditorLanguage(l);
    document.documentElement.lang = l;
    // 28.5: the language as a cookie on the origin, for server-rendered addon pages
    try {
        document.cookie = `ol-lang=${l}; path=/; max-age=31536000; SameSite=Lax`;
    } catch {
        /* ignore */
    }
}

/** Translates key, substituting `{name}` placeholders from params. */
export function t(key: string, params?: Record<string, string | number>): string {
    const entry = CATALOGUE[key];
    let text = i18n.language === 'de' && entry ? entry.de : (entry?.en ?? key);
    if (params) {
        for (const [k, v] of Object.entries(params)) text = text.replaceAll(`{${k}}`, String(v));
    }
    return text;
}

/** A key's text in both languages, for a filter that matches what the reader may have read (task 57). */
export function translations(key: string): string[] {
    const entry = CATALOGUE[key];
    return entry ? [entry.en ?? key, entry.de] : [key];
}
